<?php
declare(strict_types=1);
require __DIR__.'/config.php';require_login();require __DIR__.'/patient-layout.php';$pdo=db();
$filterText=trim((string)($_GET['q']??''));$filterAccountId=filter_input(INPUT_GET,'account_id',FILTER_VALIDATE_INT)?:0;$filterDateStart=preg_match('/^\d{4}-\d{2}-\d{2}$/',(string)($_GET['date_start']??''))?(string)$_GET['date_start']:'';$filterDateEnd=preg_match('/^\d{4}-\d{2}-\d{2}$/',(string)($_GET['date_end']??''))?(string)$_GET['date_end']:'';$dateSort=(($_GET['date_sort']??'desc')==='asc')?'asc':'desc';
$where=['TRIM(COALESCE(m.invoice_no,""))<>""'];$params=[];
if($filterAccountId>0){$where[]='m.current_account_id=?';$params[]=$filterAccountId;}if($filterDateStart!==''){$where[]='m.movement_date>=?';$params[]=$filterDateStart;}if($filterDateEnd!==''){$where[]='m.movement_date<=?';$params[]=$filterDateEnd;}
if($filterText!==''){$like='%'.$filterText.'%';$dateLike=$like;if(preg_match('/^(\d{2})\.(\d{2})\.(\d{4})$/',$filterText,$dateParts)&&checkdate((int)$dateParts[2],(int)$dateParts[1],(int)$dateParts[3]))$dateLike='%'.$dateParts[3].'-'.$dateParts[2].'-'.$dateParts[1].'%';$where[]='(COALESCE(m.invoice_no,"") LIKE ? OR COALESCE(c.code,"") LIKE ? OR COALESCE(c.title,"") LIKE ? OR COALESCE(c.short_name,"") LIKE ? OR m.movement_date LIKE ? OR EXISTS (SELECT 1 FROM stock_movements sm INNER JOIN stock_cards sc ON sc.id=sm.stock_id WHERE LOWER(TRIM(sm.invoice_no))=LOWER(TRIM(m.invoice_no)) AND sm.movement_type=m.movement_type AND (sc.stock_code LIKE ? OR sc.stock_name LIKE ?)))';array_push($params,$like,$like,$like,$like,$dateLike,$like,$like);}
$sql='SELECT MAX(m.invoice_no) invoice_no,m.movement_type,MIN(m.movement_date) movement_date,MAX(c.code) account_code,MAX(COALESCE(c.short_name,c.title)) account_name,COUNT(*) line_count,SUM(COALESCE(m.purchase_price,0)+ROUND(COALESCE(m.purchase_price,0)*COALESCE(m.vat_rate,0)/100,2)) total FROM stock_movements m LEFT JOIN current_accounts c ON c.id=m.current_account_id WHERE '.implode(' AND ',$where).' GROUP BY LOWER(TRIM(m.invoice_no)),m.movement_type ORDER BY MIN(m.movement_date) '.strtoupper($dateSort).',MAX(m.id) '.strtoupper($dateSort);$statement=$pdo->prepare($sql);$statement->execute($params);$invoices=$statement->fetchAll();
$sortQuery=http_build_query(['q'=>$filterText?:null,'account_id'=>$filterAccountId?:null,'date_start'=>$filterDateStart?:null,'date_end'=>$filterDateEnd?:null,'date_sort'=>$dateSort==='asc'?'desc':'asc']);
$accounts=$pdo->query("SELECT id,title,short_name FROM current_accounts WHERE account_type IN ('supplier','both') ORDER BY COALESCE(short_name,title)")->fetchAll();$selectedAccountName='';foreach($accounts as $account)if((int)$account['id']===$filterAccountId){$selectedAccountName=(string)($account['short_name']?:$account['title']);break;}
patient_header('Fatura Listesi','stock');?>
