<script>
(()=>{const accounts=<?=json_encode($accounts,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>,form=document.querySelector('.invoice-filter'),input=document.getElementById('invoice-account'),accountId=document.getElementById('invoice-account-id'),results=document.getElementById('invoice-account-results'),close=()=>{results.replaceChildren();results.classList.remove('open')},choose=account=>{accountId.value=String(account.id);input.value=account.short_name||account.title;close()};input.addEventListener('input',()=>{accountId.value='';const term=input.value.trim().toLocaleLowerCase('tr-TR');if(term.length<2){close();return}const found=accounts.filter(a=>((a.short_name||'')+' '+a.title).toLocaleLowerCase('tr-TR').includes(term)).slice(0,8);results.replaceChildren(...found.map(a=>{const b=document.createElement('button');b.type='button';b.textContent=a.short_name||a.title;b.onclick=()=>choose(a);return b}));results.classList.toggle('open',found.length>0)});document.addEventListener('click',event=>{if(!event.target.closest('.filter-company'))close()});form.querySelector('[data-clear="account"]').onclick=()=>{input.value='';accountId.value='';close();input.focus()};form.querySelectorAll('[data-clear="date_start"],[data-clear="date_end"]').forEach(button=>button.onclick=()=>{const field=form.querySelector('[name="'+button.dataset.clear+'"]');field.value='';field.focus()});form.addEventListener('submit',event=>{if(input.value.trim()&&!accountId.value){event.preventDefault();input.focus()}});
const table=document.querySelector('.inv-list table'),menu=document.querySelector('.column-menu'),options=document.querySelector('.column-options'),trigger=document.querySelector('.column-trigger'),headers=[...table.tHead.rows[0].cells],key='vox-invoice-list-columns';let visible;try{visible=JSON.parse(localStorage.getItem(key)||'null')}catch(e){}if(!Array.isArray(visible)||visible.length!==headers.length)visible=headers.map(()=>true);const apply=()=>{table.querySelectorAll('tr').forEach(row=>[...row.children].forEach((cell,i)=>cell.style.display=visible[i]?'':'none'));localStorage.setItem(key,JSON.stringify(visible))};options.replaceChildren(...headers.map((header,i)=>{const label=document.createElement('label'),checkbox=document.createElement('input');label.className='column-option';checkbox.type='checkbox';checkbox.checked=visible[i];checkbox.onchange=()=>{visible[i]=checkbox.checked;apply()};label.append(checkbox,document.createTextNode(header.textContent.trim()));return label}));trigger.onclick=()=>menu.classList.toggle('open');document.addEventListener('click',event=>{if(!event.target.closest('.column-picker'))menu.classList.remove('open')});apply()})();
</script>
<script>
(()=>{const form=document.querySelector('.invoice-filter');if(!form)return;const submit=()=>HTMLFormElement.prototype.submit.call(form),query=form.querySelector('input[name="q"]'),company=document.getElementById('invoice-account'),companyId=document.getElementById('invoice-account-id'),accounts=<?=json_encode($accounts,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>,matches=()=>{const term=company.value.trim().toLocaleLowerCase('tr-TR');return term.length<2?[]:accounts.filter(account=>((account.short_name||'')+' '+account.title).toLocaleLowerCase('tr-TR').includes(term))},selectAndSubmit=account=>{companyId.value=String(account.id);company.value=account.short_name||account.title;submit()};let searchTimer,companyTimer;query?.addEventListener('input',()=>{clearTimeout(searchTimer);searchTimer=setTimeout(submit,500)});query?.addEventListener('keydown',event=>{if(event.key!=='Enter')return;event.preventDefault();clearTimeout(searchTimer);submit()});company?.addEventListener('input',()=>{clearTimeout(companyTimer);companyTimer=setTimeout(()=>{const found=matches();if(found.length===1)selectAndSubmit(found[0])},500)});company?.addEventListener('keydown',event=>{if(event.key!=='Enter')return;event.preventDefault();clearTimeout(companyTimer);const found=matches();if(found.length)selectAndSubmit(found[0])});form.querySelector('.filter-results')?.addEventListener('click',event=>{if(event.target.closest('button'))setTimeout(submit,0)});form.querySelectorAll('input[type="date"]').forEach(field=>field.addEventListener('change',submit));form.querySelectorAll('.filter-clear').forEach(button=>button.addEventListener('click',()=>setTimeout(submit,0)))})();
</script>
